package com.clanpiano;

import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Damper pedal state broadcast to the party. Sent separately from notes so listeners hear the
 * same phrasing as the performer rather than a series of disconnected notes.
 * <p>
 * Serialised by the party layer's Gson instance, which needs a no-arg constructor and accessors.
 */
public class PianoSustain extends PartyMemberMessage
{
	private boolean down;

	public PianoSustain()
	{
	}

	PianoSustain(boolean down)
	{
		this.down = down;
	}

	public boolean isDown()
	{
		return down;
	}

	public void setDown(boolean down)
	{
		this.down = down;
	}
}

package com.clanpiano;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Plays the clan hall piano from a MIDI keyboard using a locally rendered piano sound, and
 * shares that performance with party members running the plugin.
 * <p>
 * The in-game piano is limited to 24 keys and quantises to the game tick, so a performance on it
 * is heavily constrained. This renders the notes locally instead, which lifts both limits. The
 * game is never driven or interacted with - the plugin only listens to your MIDI device and
 * produces sound.
 */
@PluginDescriptor(
	name = "Clan Piano MIDI",
	description = "Play the clan hall piano with a MIDI keyboard and share it with your party",
	tags = {"midi", "piano", "music", "clan", "party"}
)
public class ClanPianoPlugin extends Plugin implements MidiInput.NoteListener
{
	/** Ceiling on notes broadcast per second, to stay clear of party server throttling. */
	private static final int MAX_NOTES_PER_SECOND = 30;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private ClanPianoConfig config;

	@Inject
	private PianoAudio audio;

	private final MidiInput midiInput = new MidiInput(this);

	private ClanPianoPanel panel;
	private NavigationButton navButton;

	/**
	 * Whether the piano interface is open. Tracked from widget events and read from the MIDI
	 * thread, so it must be volatile.
	 */
	private volatile boolean pianoOpen;

	/** Guards against background tasks completing after the plugin has been turned off. */
	private volatile boolean running;

	private long sendWindowStart;
	private int sentThisWindow;

	@Override
	protected void startUp()
	{
		running = true;
		panel = new ClanPianoPanel(this::selectDevice, this::refreshDevices);

		final BufferedImage icon = ImageUtil.loadImageResource(ClanPianoPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Clan Piano MIDI")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		wsClient.registerMessage(PianoNote.class);
		wsClient.registerMessage(PianoSustain.class);

		refreshDevices();

		// Rendering the clips takes a moment, so it is kept off the client thread.
		executor.execute(() ->
		{
			audio.setNoteLength(config.noteLength() / 100.0);
			audio.warmUp(config.instrument());

			if (!running)
			{
				audio.clear();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		wsClient.unregisterMessage(PianoNote.class);
		wsClient.unregisterMessage(PianoSustain.class);
		clientToolbar.removeNavigation(navButton);
		midiInput.closeDevice();
		audio.clear();
		pianoOpen = false;
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CLAN_PIANO)
		{
			pianoOpen = true;
			updatePianoStatus();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.CLAN_PIANO)
		{
			pianoOpen = false;
			updatePianoStatus();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();

		if (state == GameState.LOADING || state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// The interface does not survive a world change, and neither should sustained notes.
			pianoOpen = false;
			updatePianoStatus();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ClanPianoConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("deviceName".equals(event.getKey()))
		{
			refreshDevices();
		}
		else if ("onlyAtPiano".equals(event.getKey()))
		{
			updatePianoStatus();
		}
		else if ("instrument".equals(event.getKey()) || "noteLength".equals(event.getKey()))
		{
			// Render up front so the first note after a change is not delayed.
			executor.execute(() ->
			{
				audio.setNoteLength(config.noteLength() / 100.0);
				audio.warmUp(config.instrument());
			});
		}
	}

	private void selectDevice(String deviceName)
	{
		// Writing config fires ConfigChanged, which reconnects.
		configManager.setConfiguration(ClanPianoConfig.GROUP, "deviceName", deviceName);
	}

	/**
	 * Rescans for MIDI inputs and reconnects. Enumerating devices touches native drivers and can
	 * block, so it is kept off both the client thread and the EDT.
	 */
	private void refreshDevices()
	{
		executor.execute(() ->
		{
			final List<String> devices = MidiInput.availableInputs();
			final String configured = config.deviceName();
			final String opened = midiInput.open(configured);

			final ClanPianoPanel p = panel;
			if (p == null)
			{
				return;
			}

			p.setDevices(devices, configured);

			if (opened != null)
			{
				p.setStatus("Connected: " + opened, true);
			}
			else if (devices.isEmpty())
			{
				p.setStatus("No MIDI inputs found", false);
			}
			else
			{
				p.setStatus("Not connected", false);
			}

			updatePianoStatus();
		});
	}

	private void updatePianoStatus()
	{
		final ClanPianoPanel p = panel;

		if (p == null)
		{
			return;
		}

		if (!config.onlyAtPiano())
		{
			p.setPianoStatus("Playing anywhere");
		}
		else
		{
			p.setPianoStatus(pianoOpen ? "At the piano" : "Open the piano to play");
		}
	}

	@Override
	public void onNote(int note, int velocity, boolean on)
	{
		if (config.onlyAtPiano() && !pianoOpen)
		{
			return;
		}

		final int shifted = note + config.transpose();

		if (shifted < 0 || shifted > 127)
		{
			return;
		}

		if (!on)
		{
			// A clip cannot be stopped once started, so note-offs have nothing to act on and are
			// not worth the party traffic.
			return;
		}

		audio.play(shifted, velocity, config.volume(), config.instrument());

		if (config.broadcast() && partyService.isInParty() && allowSend())
		{
			partyService.send(new PianoNote(shifted, velocity, true, config.instrument()));
		}
	}

	/**
	 * Crude rate limit so a fast passage cannot flood the party server. Dropping a note is
	 * preferable to being throttled mid-performance.
	 */
	private synchronized boolean allowSend()
	{
		final long now = System.currentTimeMillis();

		if (now - sendWindowStart >= 1000L)
		{
			sendWindowStart = now;
			sentThisWindow = 0;
		}

		if (sentThisWindow >= MAX_NOTES_PER_SECOND)
		{
			return false;
		}

		sentThisWindow++;
		return true;
	}

	@Override
	public void onSustain(boolean down)
	{
		if (config.onlyAtPiano() && !pianoOpen)
		{
			return;
		}

		audio.setSustain(down);

		// Never rate limited: a dropped pedal-up would sustain the whole performance.
		if (config.broadcast() && partyService.isInParty())
		{
			partyService.send(new PianoSustain(down));
		}
	}

	/** Pedal changes broadcast by other party members. */
	@Subscribe
	public void onPianoSustain(PianoSustain event)
	{
		if (!config.listen())
		{
			return;
		}

		final PartyMember local = partyService.getLocalMember();

		if (local != null && event.getMemberId() == local.getMemberId())
		{
			// Our own pedal echoed back; already applied locally.
			return;
		}

		audio.setSustain(event.isDown());
	}

	/** Notes broadcast by other party members. */
	@Subscribe
	public void onPianoNote(PianoNote event)
	{
		if (!config.listen())
		{
			return;
		}

		final PartyMember local = partyService.getLocalMember();

		if (local != null && event.getMemberId() == local.getMemberId())
		{
			// Our own note echoed back; already played locally.
			return;
		}

		if (event.isOn())
		{
			audio.play(event.getNote(), event.getVelocity(), config.volume(),
				event.resolveInstrument(config.instrument()));
		}
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		// A member leaving mid-phrase would otherwise leave notes sustaining forever.
	}

	@Provides
	ClanPianoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClanPianoConfig.class);
	}
}

package com.clanpiano;

/**
 * Tone presets. Each is a set of harmonic strengths plus a decay shape, which together are
 * enough to suggest a recognisable instrument without shipping any samples.
 * <p>
 * {@code harmonics[0]} is the fundamental and each entry after it is the next partial up. A
 * bright instrument keeps energy in the upper partials; a mellow one drops away quickly. Missing
 * partials matter as much as present ones - the hollow character of a music box comes from its
 * near-absent even harmonics.
 */
public enum Instrument
{
	GRAND_PIANO("Grand piano",
		new double[]{1.0, 0.45, 0.22, 0.12, 0.06},
		3.0, 0.55, 0.9, 3.2, 0.004, 1, 16, 0.0, 0.0),

	BRIGHT_PIANO("Bright piano",
		new double[]{1.0, 0.62, 0.44, 0.30, 0.20, 0.11},
		3.2, 0.45, 0.9, 3.0, 0.003, 1, 16, 0.0, 0.0),

	/** Two strings a shade out of tune with each other, which is what gives it the saloon beat. */
	HONKY_TONK("Honky-tonk piano",
		new double[]{1.0, 0.50, 0.30, 0.18, 0.10, 0.05},
		3.0, 0.50, 0.9, 3.0, 0.004, 1, 16, 0.0, 22.0),

	ELECTRIC_PIANO("Electric piano",
		new double[]{1.0, 0.18, 0.55, 0.10, 0.28, 0.08},
		2.2, 0.70, 1.2, 3.6, 0.006, 1, 16, -1.0, 0.0),

	HARPSICHORD("Harpsichord",
		new double[]{1.0, 0.80, 0.62, 0.48, 0.36, 0.26, 0.16},
		5.2, 0.35, 0.6, 1.6, 0.002, 1, 16, 0.0, 4.0),

	MUSIC_BOX("Music box",
		new double[]{1.0, 0.05, 0.48, 0.03, 0.30, 0.02, 0.14},
		3.8, 0.30, 1.1, 3.4, 0.002, 1, 16, -1.0, 0.0),

	MARIMBA("Marimba",
		new double[]{1.0, 0.02, 0.05, 0.34, 0.03, 0.10},
		6.2, 0.40, 0.6, 1.4, 0.002, 1, 16, 0.0, 0.0),

	/**
	 * Barely decays, so unlike the struck instruments its energy stays high for the whole clip.
	 * Peak normalisation alone would leave it far louder than the others, hence the level trim
	 * and the shorter default length.
	 */
	ORGAN("Organ",
		new double[]{1.0, 0.55, 0.70, 0.32, 0.45, 0.20, 0.28},
		0.15, 0.10, 0.7, 2.2, 0.020, 1, 16, -7.0, 0.0),

	/**
	 * The game's own audio is built from short, low-rate, low-bit samples, and that coarseness is
	 * most of what makes it recognisable. Decimating and bit-crushing an otherwise plain tone
	 * reproduces the character far better than any choice of harmonics alone.
	 */
	RUNESCAPE("RuneScape piano",
		new double[]{1.0, 0.28, 0.52, 0.16, 0.30, 0.09},
		3.4, 0.40, 0.8, 2.6, 0.003, 2, 8, -2.0, 0.0);

	private final String name;
	final double[] harmonics;

	/** Base decay rate; higher fades faster. Near zero holds a steady tone. */
	final double decay;

	/** How much faster each successive harmonic fades relative to the fundamental. */
	final double harmonicDecaySpread;

	final double dampedSeconds;
	final double sustainedSeconds;
	final double attackSeconds;

	/** Repeat each sample this many times, lowering the effective rate. 1 leaves it untouched. */
	final int sampleHold;

	/** Quantise to this many bits. 16 leaves it untouched. */
	final int bitDepth;

	/**
	 * Level adjustment in decibels, applied at playback. Peak normalisation equalises peaks but
	 * not perceived loudness, so instruments that decay slowly need pulling down to match.
	 */
	final double levelTrim;

	/** Detune in cents between two voices. 0 renders a single voice. */
	final double detuneCents;

	Instrument(String name, double[] harmonics, double decay, double harmonicDecaySpread,
		double dampedSeconds, double sustainedSeconds, double attackSeconds,
		int sampleHold, int bitDepth, double levelTrim, double detuneCents)
	{
		this.name = name;
		this.harmonics = harmonics;
		this.decay = decay;
		this.harmonicDecaySpread = harmonicDecaySpread;
		this.dampedSeconds = dampedSeconds;
		this.sustainedSeconds = sustainedSeconds;
		this.attackSeconds = attackSeconds;
		this.sampleHold = sampleHold;
		this.bitDepth = bitDepth;
		this.levelTrim = levelTrim;
		this.detuneCents = detuneCents;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.clanpiano;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel letting the user pick their MIDI input from a live list rather than typing a name.
 */
class ClanPianoPanel extends PluginPanel
{
	/** Placeholder entry meaning "use the first physical input found", stored as a blank filter. */
	private static final String AUTO = "Auto-detect";

	private final JComboBox<String> deviceBox = new JComboBox<>();
	private final JLabel status = new JLabel("Not connected");
	private final JLabel pianoStatus = new JLabel("Open the piano to play");
	private final Consumer<String> onDeviceSelected;

	/** Suppresses the action listener while the combo is being repopulated in code. */
	private boolean updating;

	ClanPianoPanel(Consumer<String> onDeviceSelected, Runnable onRefresh)
	{
		this.onDeviceSelected = onDeviceSelected;

		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setLayout(new BorderLayout());

		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		content.add(heading("MIDI input"));
		content.add(Box.createVerticalStrut(4));

		deviceBox.setFocusable(false);
		deviceBox.addActionListener(e ->
		{
			if (updating)
			{
				return;
			}

			final Object selected = deviceBox.getSelectedItem();

			if (selected != null)
			{
				this.onDeviceSelected.accept(AUTO.equals(selected) ? "" : selected.toString());
			}
		});
		content.add(align(deviceBox));

		content.add(Box.createVerticalStrut(8));

		final JButton refresh = new JButton("Rescan devices");
		refresh.setFocusable(false);
		refresh.addActionListener(e -> onRefresh.run());
		content.add(align(refresh));

		content.add(Box.createVerticalStrut(12));

		final JPanel statusRow = new JPanel(new GridLayout(0, 1));
		statusRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		statusRow.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		pianoStatus.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusRow.add(status);
		statusRow.add(pianoStatus);
		content.add(align(statusRow));

		add(content, BorderLayout.NORTH);
	}

	private static JLabel heading(String text)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.BRAND_ORANGE);
		return align(label);
	}

	private static <T extends JComponent> T align(T component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
		return component;
	}

	/** Repopulates the dropdown. Safe to call from any thread. */
	void setDevices(List<String> devices, String selected)
	{
		SwingUtilities.invokeLater(() ->
		{
			updating = true;
			try
			{
				deviceBox.removeAllItems();
				deviceBox.addItem(AUTO);

				for (String device : devices)
				{
					deviceBox.addItem(device);
				}

				if (selected == null || selected.isEmpty() || !devices.contains(selected))
				{
					deviceBox.setSelectedItem(AUTO);
				}
				else
				{
					deviceBox.setSelectedItem(selected);
				}
			}
			finally
			{
				updating = false;
			}
		});
	}

	/** Updates the "at the piano" line. Safe to call from any thread. */
	void setPianoStatus(String text)
	{
		SwingUtilities.invokeLater(() -> pianoStatus.setText(text));
	}

	/** Updates the status line. Safe to call from any thread. */
	void setStatus(String text, boolean connected)
	{
		SwingUtilities.invokeLater(() ->
		{
			status.setText(text);
			status.setForeground(connected ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
		});
	}
}

package com.clanpiano;

import java.util.ArrayList;
import java.util.List;
import javax.sound.midi.MidiDevice;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.MidiUnavailableException;
import javax.sound.midi.Receiver;
import javax.sound.midi.Sequencer;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Synthesizer;
import javax.sound.midi.Transmitter;
import lombok.extern.slf4j.Slf4j;

/**
 * Owns the connection to a hardware MIDI input and turns raw MIDI messages into note on/off
 * callbacks. Callbacks arrive on a MIDI system thread, never the client thread.
 */
@Slf4j
class MidiInput implements Receiver
{
	/** MIDI CC 64 is the damper (sustain) pedal. */
	private static final int CC_SUSTAIN = 64;

	/** Controllers report the pedal as a continuous value; at or above halfway counts as down. */
	private static final int PEDAL_THRESHOLD = 64;

	interface NoteListener
	{
		void onNote(int note, int velocity, boolean on);

		void onSustain(boolean down);
	}

	private final NoteListener listener;

	private MidiDevice device;
	private Transmitter transmitter;

	MidiInput(NoteListener listener)
	{
		this.listener = listener;
	}

	/**
	 * Names of every physical MIDI input, in the order they are offered by the system.
	 * <p>
	 * Java always reports a software sequencer and synthesizer alongside real ports. The
	 * sequencer in particular advertises a transmitter, so it would otherwise be picked ahead of
	 * an actual keyboard during auto-detection.
	 */
	static List<String> availableInputs()
	{
		final List<String> names = new ArrayList<>();

		for (MidiDevice.Info info : MidiSystem.getMidiDeviceInfo())
		{
			try (MidiDevice d = MidiSystem.getMidiDevice(info))
			{
				if (isHardwareInput(d))
				{
					names.add(info.getName());
				}
			}
			catch (MidiUnavailableException ignored)
			{
				// Held by another process or unplugged mid-scan; nothing useful to report.
			}
		}

		return names;
	}

	private static boolean isHardwareInput(MidiDevice d)
	{
		// A transmitter is what makes a device an input. getMaxTransmitters() is -1 for unlimited.
		return d.getMaxTransmitters() != 0
			&& !(d instanceof Sequencer)
			&& !(d instanceof Synthesizer);
	}

	/**
	 * Opens the input whose name contains {@code nameFilter}, or the first physical input when
	 * the filter is blank.
	 *
	 * @return the name of the opened device, or null if nothing suitable was found
	 */
	synchronized String open(String nameFilter)
	{
		closeDevice();

		final String filter = nameFilter == null ? "" : nameFilter.trim().toLowerCase();

		for (MidiDevice.Info info : MidiSystem.getMidiDeviceInfo())
		{
			MidiDevice candidate;
			try
			{
				candidate = MidiSystem.getMidiDevice(info);
			}
			catch (MidiUnavailableException e)
			{
				continue;
			}

			final String name = info.getName();

			if (!isHardwareInput(candidate)
				|| (!filter.isEmpty() && !name.toLowerCase().contains(filter)))
			{
				candidate.close();
				continue;
			}

			try
			{
				candidate.open();
				Transmitter tx = candidate.getTransmitter();
				tx.setReceiver(this);

				device = candidate;
				transmitter = tx;
				log.debug("Opened MIDI input {}", name);
				return name;
			}
			catch (MidiUnavailableException e)
			{
				log.debug("Could not open MIDI input {}", name, e);
				candidate.close();
			}
		}

		return null;
	}

	synchronized void closeDevice()
	{
		if (transmitter != null)
		{
			transmitter.close();
			transmitter = null;
		}

		if (device != null)
		{
			device.close();
			device = null;
		}
	}

	@Override
	public void send(MidiMessage message, long timeStamp)
	{
		if (!(message instanceof ShortMessage))
		{
			return;
		}

		final ShortMessage sm = (ShortMessage) message;
		final int command = sm.getCommand();
		final int note = sm.getData1();
		final int velocity = sm.getData2();

		if (command == ShortMessage.NOTE_ON && velocity > 0)
		{
			listener.onNote(note, velocity, true);
		}
		else if (command == ShortMessage.NOTE_OFF || (command == ShortMessage.NOTE_ON && velocity == 0))
		{
			// Many controllers send NOTE_ON with zero velocity in place of NOTE_OFF.
			listener.onNote(note, 0, false);
		}
		else if (command == ShortMessage.CONTROL_CHANGE && note == CC_SUSTAIN)
		{
			// Half-pedalling is not modelled; the pedal is treated as a simple switch.
			listener.onSustain(velocity >= PEDAL_THRESHOLD);
		}
	}

	/**
	 * Receiver#close, called by the MIDI system when the transmitter goes away. The device
	 * lifecycle is owned by {@link #closeDevice()}, so there is nothing to do here.
	 */
	@Override
	public void close()
	{
	}
}

package com.clanpiano;

import java.io.ByteArrayOutputStream;
import java.io.IOException;

/**
 * Renders a piano-like note into WAV bytes.
 * <p>
 * {@link net.runelite.client.audio.AudioPlayer} plays an audio stream, so the tone has to exist
 * as encoded audio rather than being generated by a synthesizer. The WAV container is written by
 * hand here - it is a short, well-specified header, and building it directly avoids pulling in an
 * audio framework just to package some samples.
 * <p>
 * The timbre is additive: a fundamental plus a few decaying harmonics, shaped by a fast attack
 * and an exponential decay. It is not a sampled piano, but it reads as one.
 */
final class ToneGenerator
{
	private static final int SAMPLE_RATE = 22050;
	private static final int BITS = 16;
	private static final double TWO_PI = Math.PI * 2.0;

	/** Seconds of fade at the very end, so the clip never cuts off with a click. */
	private static final double RELEASE = 0.05;

	private ToneGenerator()
	{
	}

	/**
	 * @param midiNote   MIDI note number, 69 being A440
	 * @param seconds    total length of the clip
	 * @param instrument tone preset supplying the harmonics and decay shape
	 * @return a complete mono 16-bit WAV file
	 */
	static byte[] wav(int midiNote, double seconds, Instrument instrument)
	{
		final double[] harmonics = instrument.harmonics;

		final double frequency = 440.0 * Math.pow(2.0, (midiNote - 69) / 12.0);

		// A second voice a few cents away beats against the first; 0 cents renders one voice.
		final boolean detuned = instrument.detuneCents != 0.0;
		final double detuneRatio = Math.pow(2.0, instrument.detuneCents / 1200.0);
		final int frames = (int) (SAMPLE_RATE * seconds);
		final short[] samples = new short[frames];

		// Higher notes decay faster, as they do on a real instrument.
		final double decay = instrument.decay + (midiNote - 60) * instrument.decay * 0.02;

		double peak = 0.0;
		final double[] raw = new double[frames];

		for (int i = 0; i < frames; i++)
		{
			final double t = i / (double) SAMPLE_RATE;
			double value = 0.0;

			for (int h = 0; h < harmonics.length; h++)
			{
				final double harmonicFreq = frequency * (h + 1);

				if (harmonicFreq >= SAMPLE_RATE / 2.0)
				{
					// Above Nyquist this would alias into an audible lower tone.
					break;
				}

				// Upper harmonics fade faster than the fundamental, as the note rings out.
				final double harmonicDecay =
					Math.exp(-decay * t * (1.0 + h * instrument.harmonicDecaySpread));

				double partial = Math.sin(TWO_PI * harmonicFreq * t);

				if (detuned)
				{
					partial = (partial + Math.sin(TWO_PI * harmonicFreq * detuneRatio * t)) * 0.5;
				}

				value += harmonics[h] * harmonicDecay * partial;
			}

			// A short attack ramp, otherwise the onset clicks.
			final double attack = Math.min(1.0, t / instrument.attackSeconds);

			final double remaining = seconds - t;
			final double release = remaining < RELEASE ? remaining / RELEASE : 1.0;

			raw[i] = value * attack * release;
			peak = Math.max(peak, Math.abs(raw[i]));
		}

		// Normalise so every note leaves at a consistent level; velocity is applied at playback.
		final double scale = peak > 0 ? (Short.MAX_VALUE * 0.85) / peak : 0.0;

		for (int i = 0; i < frames; i++)
		{
			// Sample-and-hold lowers the effective rate. The aliasing it introduces is part of
			// the lo-fi character rather than something to filter away.
			final int source = instrument.sampleHold > 1
				? (i / instrument.sampleHold) * instrument.sampleHold
				: i;

			int value = (int) (raw[source] * scale);

			if (instrument.bitDepth < BITS)
			{
				final int step = 1 << (BITS - instrument.bitDepth);
				value = Math.round((float) value / step) * step;
				value = Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE, value));
			}

			samples[i] = (short) value;
		}

		return encode(samples);
	}

	/** Wraps PCM samples in a canonical 44-byte WAV header. */
	private static byte[] encode(short[] samples)
	{
		final int dataLength = samples.length * 2;
		final ByteArrayOutputStream out = new ByteArrayOutputStream(44 + dataLength);

		try
		{
			out.write(new byte[]{'R', 'I', 'F', 'F'});
			writeInt(out, 36 + dataLength);
			out.write(new byte[]{'W', 'A', 'V', 'E'});

			out.write(new byte[]{'f', 'm', 't', ' '});
			writeInt(out, 16);
			writeShort(out, 1);
			writeShort(out, 1);
			writeInt(out, SAMPLE_RATE);
			writeInt(out, SAMPLE_RATE * BITS / 8);
			writeShort(out, BITS / 8);
			writeShort(out, BITS);

			out.write(new byte[]{'d', 'a', 't', 'a'});
			writeInt(out, dataLength);

			for (short sample : samples)
			{
				writeShort(out, sample);
			}
		}
		catch (IOException e)
		{
			// ByteArrayOutputStream does not perform IO and cannot fail.
			throw new IllegalStateException(e);
		}

		return out.toByteArray();
	}

	private static void writeInt(ByteArrayOutputStream out, int value)
	{
		out.write(value & 0xFF);
		out.write((value >> 8) & 0xFF);
		out.write((value >> 16) & 0xFF);
		out.write((value >> 24) & 0xFF);
	}

	private static void writeShort(ByteArrayOutputStream out, int value)
	{
		out.write(value & 0xFF);
		out.write((value >> 8) & 0xFF);
	}
}

package com.clanpiano;

import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * A single note on/off broadcast to the party. Kept deliberately small because a fast passage
 * produces a lot of these.
 * <p>
 * Serialised by the party layer's Gson instance, which needs a no-arg constructor and accessors.
 */
public class PianoNote extends PartyMemberMessage
{
	private int note;
	private int velocity;
	private boolean on;

	/**
	 * Instrument name, so listeners hear the performance as the player intended rather than
	 * through their own setting. Absent from older senders, which callers treat as unspecified.
	 */
	private String instrument;

	public PianoNote()
	{
	}

	PianoNote(int note, int velocity, boolean on, Instrument instrument)
	{
		this.note = note;
		this.velocity = velocity;
		this.on = on;
		this.instrument = instrument.name();
	}

	/** @return the sender's instrument, or {@code fallback} if they did not specify one. */
	Instrument resolveInstrument(Instrument fallback)
	{
		if (instrument == null)
		{
			return fallback;
		}

		try
		{
			return Instrument.valueOf(instrument);
		}
		catch (IllegalArgumentException e)
		{
			// A newer sender used an instrument this version does not know about.
			return fallback;
		}
	}

	public int getNote()
	{
		return note;
	}

	public void setNote(int note)
	{
		this.note = note;
	}

	public int getVelocity()
	{
		return velocity;
	}

	public void setVelocity(int velocity)
	{
		this.velocity = velocity;
	}

	public boolean isOn()
	{
		return on;
	}

	public String getInstrument()
	{
		return instrument;
	}

	public void setInstrument(String instrument)
	{
		this.instrument = instrument;
	}

	public void setOn(boolean on)
	{
		this.on = on;
	}
}

package com.clanpiano;

import java.io.ByteArrayInputStream;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Plays notes through {@link AudioPlayer}.
 * <p>
 * AudioPlayer starts a sound and returns nothing, so a note cannot be stopped once it has begun.
 * That rules out true note-off and true damping: every note rings for the length of its clip. To
 * keep the sustain pedal meaningful, two lengths are rendered per note and the pedal selects
 * between them - a short, quickly damped clip normally, and a long ringing one while held.
 */
@Slf4j
@Singleton
class PianoAudio
{
	private static final int MIN_NOTE = 21;
	private static final int MAX_NOTE = 108;

	/**
	 * Upper bound on cached clips. Each is tens of kilobytes, and every instrument doubles the
	 * possible entries, so the cache is emptied rather than allowed to grow indefinitely.
	 */
	private static final int MAX_CACHED_CLIPS = 240;

	/** Rendered clips, keyed by note, pedal state and instrument. Built on first use. */
	private final Map<Integer, byte[]> clips = new ConcurrentHashMap<>();

	private final AudioPlayer audioPlayer;

	private volatile boolean sustain;

	/** Multiplier on every clip length, from the note-length setting. */
	private volatile double lengthScale = 1.0;

	@Inject
	PianoAudio(AudioPlayer audioPlayer)
	{
		this.audioPlayer = audioPlayer;
	}

	/** Changing the length invalidates every rendered clip, so the cache is dropped. */
	void setNoteLength(double scale)
	{
		if (Math.abs(scale - lengthScale) > 0.001)
		{
			lengthScale = scale;
			clips.clear();
		}
	}

	void setSustain(boolean down)
	{
		sustain = down;
	}

	boolean isSustain()
	{
		return sustain;
	}

	/**
	 * @param volume  configured volume, 0-127
	 * @param velocity how hard the key was struck, 1-127
	 */
	void play(int note, int velocity, int volume, Instrument instrument)
	{
		if (note < MIN_NOTE || note > MAX_NOTE)
		{
			return;
		}

		final boolean held = sustain;
		final byte[] clip = clip(note, held, instrument);

		try
		{
			audioPlayer.play(new ByteArrayInputStream(clip), gain(velocity, volume, instrument));
		}
		catch (Exception e)
		{
			// A line can be unavailable if the mixer is busy; dropping the note is better than
			// interrupting the performance with an error.
			log.debug("Could not play note {}", note, e);
		}
	}

	/** Combines configured volume, key velocity and the instrument's trim into a gain in decibels. */
	private static float gain(int velocity, int volume, Instrument instrument)
	{
		final double v = Math.max(1, Math.min(127, velocity)) / 127.0;
		final double vol = Math.max(0, Math.min(127, volume)) / 127.0;
		final double amplitude = v * vol;

		if (amplitude <= 0.0001)
		{
			return -80f;
		}

		return (float) Math.max(-80.0, 20.0 * Math.log10(amplitude) + instrument.levelTrim);
	}

	/** Renders a clip, reusing a cached one where possible. */
	private byte[] clip(int note, boolean held, Instrument instrument)
	{
		final int key = (note * 2 + (held ? 1 : 0)) * Instrument.values().length + instrument.ordinal();
		final byte[] cached = clips.get(key);

		if (cached != null)
		{
			return cached;
		}

		if (clips.size() >= MAX_CACHED_CLIPS)
		{
			// Switching instruments repeatedly would otherwise accumulate every combination.
			clips.clear();
		}

		final double seconds =
			(held ? instrument.sustainedSeconds : instrument.dampedSeconds) * lengthScale;
		final byte[] rendered = ToneGenerator.wav(note, seconds, instrument);
		clips.put(key, rendered);
		return rendered;
	}

	/**
	 * Pre-renders the clips so the first note of a performance is not delayed by generating one.
	 * Only the range the clan hall piano covers is warmed; anything outside it, and the sustained
	 * variants, are generated on demand.
	 */
	void warmUp(Instrument instrument)
	{
		for (int note = 60; note < 84; note++)
		{
			clip(note, false, instrument);
		}
	}

	void clear()
	{
		clips.clear();
		sustain = false;
	}
}

